import { WritableLike } from '../..';

declare namespace stream {
    interface BaseErrorBoosterStreamOptions {
        project: string;
        service?: string;
        fields?: {
            additional: Record<string, unknown>
        }
    }
    export interface ErrorBoosterUnixStreamOptions extends BaseErrorBoosterStreamOptions {
        socketType?: 'unix_dgram';
        socketPath: string;
    }
    export interface ErrorBoosterHttpStreamOptions extends BaseErrorBoosterStreamOptions {
        socketType: 'http';
        socketHost?: string;
        socketPort?: number;
        socketPath?: string;
        maxTotalSockets?: number;
    }
    export type ErrorBoosterStreamOptions = ErrorBoosterUnixStreamOptions | ErrorBoosterHttpStreamOptions;
}

declare function stream(config?: stream.ErrorBoosterStreamOptions): WritableLike;

export = stream;
